} catch (error) {
  ai = {
    lead_score: 50,
    lead_type: 'Warm',
    urgency: 'Normal',
    summary: 'Could not parse AI response.',
    estimated_budget_numeric: null,
    preferred_size: null,
    bedrooms: null,
    bathrooms: null,
    property_condition: 'unknown',
    next_action: 'Manual review needed.'
  };
}

return [
  {
    json: {
      ...$json,
      ...ai
    }
  }
];

