const warmDays = [2, 5, 10, 21, 45];
const coldDays = [5, 12, 25, 45, 75];
const timeZone = 'America/Chicago';

function localDateKey(date, tz) {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: tz,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(new Date(date));

  const y = parts.find(p => p.type === 'year').value;
  const m = parts.find(p => p.type === 'month').value;
  const d = parts.find(p => p.type === 'day').value;

  return `${y}-${m}-${d}`;
}

function addDays(date, days) {
  const d = new Date(date);
  d.setDate(d.getDate() + days);
  return d;
}

const now = new Date();
const todayKey = localDateKey(now, timeZone);

return items
  .filter(item => {
    const j = item.json;

    const email = String(j.Email || '').trim();
    const replyStatus = String(j['Reply Status'] || '').trim().toLowerCase();
    const appointmentStatus = String(j['Appointment Status'] || '').trim().toLowerCase();
    const leadType = String(j['Lead Type'] || '').trim().toLowerCase();
    const followupCount = Number(j['Follow up count'] || 0);

    if (!email) return false;
    if (replyStatus === 'replied') return false;
    if (appointmentStatus === 'booked') return false;
    if (leadType === 'hot') return false;
    if (followupCount >= 5) return false;
    if (!['warm', 'cold'].includes(leadType)) return false;

    const cadence = leadType === 'warm' ? warmDays : coldDays;
    const requiredDays = cadence[followupCount];
    if (requiredDays === undefined) return false;

    const nextRaw = String(j['Next Followup At'] || '').trim();
    const lastRaw = String(j['Last Followup At'] || j['Created At'] || '').trim();

    let dueDate;

    if (nextRaw) {
      dueDate = new Date(nextRaw);
    } else if (lastRaw) {
      dueDate = addDays(new Date(lastRaw), requiredDays);
    } else {
      return false;
    }

    if (isNaN(dueDate.getTime())) return false;

    const dueKey = localDateKey(dueDate, timeZone);
    return dueKey <= todayKey;
  })
  .map(item => {
    const j = item.json;

    const leadType = String(j['Lead Type'] || '').trim().toLowerCase();
    const cadence = leadType === 'warm' ? warmDays : coldDays;

    const currentCount = Number(j['Follow up count'] || 0);
    const nextCount = currentCount + 1;

    const hasMore = nextCount < cadence.length;
    const nextDays = hasMore ? cadence[nextCount] : null;

    j.followup_type = leadType;
    j.followup_number = nextCount;
    j.has_more_followups = hasMore;
    j.next_followup_days = nextDays;
    j.next_followup_at_new = hasMore ? addDays(now, nextDays).toISOString() : '';

    return item;
  });

